window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-76e4a5f8f063993d"]={"versions": [{"id": "FIG-76e4a5f8f063993d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles SPEM-basiertes Metamodell- bzw. Methodik-Diagramm (Methodology Content Definition) aus der AUTOSAR Methodology. Das Diagramm definiert die Kernbestandteile einer wiederverwendbaren Aufgabenbeschreibung (<code>Task Definition</code>) und stellt deren statische sowie funktionale Beziehungen zu Rollen, Werkzeugen und Arbeitsergebnissen (Work Products) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die <code>Task Definition</code> (dargestellt als pfeilförmiger Prozessbaustein). Die assoziierten Entitäten und Schnittstellen umfassen:</p>\n<ul class=\"fig-list\"><li><code>Role Definition</code> (Piktogramm Person): Über eine gerichtete Assoziation mit dem Stereotyp <code>«performs»</code> mit der Task Definition verbunden (beschreibt die ausführende Rolle).\n</li><li><code>Tool Definition</code> (Piktogramm Hammer): Verbunden über eine gerichtete Kante mit dem Stereotyp <code>«used tool»</code>, ausgehend von der Task Definition hin zum Werkzeug.\n</li><li>Eingangs-Arbeitsergebnis (Dokumentensymbol links): Gerichtete Beziehung mit Stereotyp <code>«input»</code> und Kardinalität <code>0..*</code> auf die Task Definition.\n</li><li>Ausgangs-Arbeitsergebnis (Dokumentensymbol rechts): Gerichtete Beziehung mit Stereotyp <code>«output»</code> und Kardinalität <code>0..*</code> von der Task Definition auf das Dokumentensymbol.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein Transformations- und Rollenzuordnungsmuster ab:</p>\n<ol class=\"fig-list\"><li>Eine oder mehrere <code>Role Definition</code> führen die <code>Task Definition</code> aus (<code>«performs»</code>).\n</li><li>Die Task Definition konsumiert null bis beliebig viele Eingangs-Work-Products (<code>«input»</code>, <code>0..*</code>).\n</li><li>Zur Durchführung greift die Task Definition auf unterstützende Werkzeuge zu (<code>«used tool»</code> auf <code>Tool Definition</code>).\n</li><li>Als Ergebnis erzeugt oder aktualisiert die Task Definition null bis beliebig viele Ausgangs-Work-Products (<code>«output»</code>, <code>0..*</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für AUTOSAR-Methodik- und Prozessbeschreibungen. Für Prozessmodellierer und Tool-Entwickler verbindlich:</p>\n<ul class=\"fig-list\"><li>Aufgaben (<code>Task Definition</code>) sind deklarativ und prozessunabhängig wiederverwendbar.\n</li><li>Kardinalitäten von <code>0..*</code> für Ein- und Ausgänge kennzeichnen optionale bzw. mehrfache Artefakte.\n</li><li>Rollen und Werkzeuge sind als wiederverwendbare Definitionsbausteine von konkreten Instanziierungen (Use Cases) entkoppelt.\n</li></ul>"}, {"id": "FIG-08eb36f0a7c274bc", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles SPEM-basiertes Metamodell- bzw. Methodik-Diagramm (Methodology Content Definition) aus der AUTOSAR Methodology. Das Diagramm definiert die Kernbestandteile einer wiederverwendbaren Aufgabenbeschreibung (<code>Task Definition</code>) und stellt deren statische sowie funktionale Beziehungen zu Rollen, Werkzeugen und Arbeitsergebnissen (Work Products) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die <code>Task Definition</code> (dargestellt als pfeilförmiger Prozessbaustein). Die assoziierten Entitäten und Schnittstellen umfassen:</p>\n<ul class=\"fig-list\"><li><code>Role Definition</code> (Piktogramm Person): Über eine gerichtete Assoziation mit dem Stereotyp <code>«performs»</code> mit der Task Definition verbunden (beschreibt die ausführende Rolle).\n</li><li><code>Tool Definition</code> (Piktogramm Hammer): Verbunden über eine gerichtete Kante mit dem Stereotyp <code>«used tool»</code>, ausgehend von der Task Definition hin zum Werkzeug.\n</li><li>Eingangs-Arbeitsergebnis (Dokumentensymbol links): Gerichtete Beziehung mit Stereotyp <code>«input»</code> und Kardinalität <code>0..*</code> auf die Task Definition.\n</li><li>Ausgangs-Arbeitsergebnis (Dokumentensymbol rechts): Gerichtete Beziehung mit Stereotyp <code>«output»</code> und Kardinalität <code>0..*</code> von der Task Definition auf das Dokumentensymbol.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein Transformations- und Rollenzuordnungsmuster ab:</p>\n<ol class=\"fig-list\"><li>Eine oder mehrere <code>Role Definition</code> führen die <code>Task Definition</code> aus (<code>«performs»</code>).\n</li><li>Die Task Definition konsumiert null bis beliebig viele Eingangs-Work-Products (<code>«input»</code>, <code>0..*</code>).\n</li><li>Zur Durchführung greift die Task Definition auf unterstützende Werkzeuge zu (<code>«used tool»</code> auf <code>Tool Definition</code>).\n</li><li>Als Ergebnis erzeugt oder aktualisiert die Task Definition null bis beliebig viele Ausgangs-Work-Products (<code>«output»</code>, <code>0..*</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für AUTOSAR-Methodik- und Prozessbeschreibungen. Für Prozessmodellierer und Tool-Entwickler verbindlich:</p>\n<ul class=\"fig-list\"><li>Aufgaben (<code>Task Definition</code>) sind deklarativ und prozessunabhängig wiederverwendbar.\n</li><li>Kardinalitäten von <code>0..*</code> für Ein- und Ausgänge kennzeichnen optionale bzw. mehrfache Artefakte.\n</li><li>Rollen und Werkzeuge sind als wiederverwendbare Definitionsbausteine von konkreten Instanziierungen (Use Cases) entkoppelt.\n</li></ul>"}, {"id": "FIG-e26d09c9bb86b012", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles SPEM-basiertes Metamodell- bzw. Methodik-Diagramm (Methodology Content Definition) aus der AUTOSAR Methodology. Das Diagramm definiert die Kernbestandteile einer wiederverwendbaren Aufgabenbeschreibung (<code>Task Definition</code>) und stellt deren statische sowie funktionale Beziehungen zu Rollen, Werkzeugen und Arbeitsergebnissen (Work Products) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die <code>Task Definition</code> (dargestellt als pfeilförmiger Prozessbaustein). Die assoziierten Entitäten und Schnittstellen umfassen:</p>\n<ul class=\"fig-list\"><li><code>Role Definition</code> (Piktogramm Person): Über eine gerichtete Assoziation mit dem Stereotyp <code>«performs»</code> mit der Task Definition verbunden (beschreibt die ausführende Rolle).\n</li><li><code>Tool Definition</code> (Piktogramm Hammer): Verbunden über eine gerichtete Kante mit dem Stereotyp <code>«used tool»</code>, ausgehend von der Task Definition hin zum Werkzeug.\n</li><li>Eingangs-Arbeitsergebnis (Dokumentensymbol links): Gerichtete Beziehung mit Stereotyp <code>«input»</code> und Kardinalität <code>0..*</code> auf die Task Definition.\n</li><li>Ausgangs-Arbeitsergebnis (Dokumentensymbol rechts): Gerichtete Beziehung mit Stereotyp <code>«output»</code> und Kardinalität <code>0..*</code> von der Task Definition auf das Dokumentensymbol.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein Transformations- und Rollenzuordnungsmuster ab:</p>\n<ol class=\"fig-list\"><li>Eine oder mehrere <code>Role Definition</code> führen die <code>Task Definition</code> aus (<code>«performs»</code>).\n</li><li>Die Task Definition konsumiert null bis beliebig viele Eingangs-Work-Products (<code>«input»</code>, <code>0..*</code>).\n</li><li>Zur Durchführung greift die Task Definition auf unterstützende Werkzeuge zu (<code>«used tool»</code> auf <code>Tool Definition</code>).\n</li><li>Als Ergebnis erzeugt oder aktualisiert die Task Definition null bis beliebig viele Ausgangs-Work-Products (<code>«output»</code>, <code>0..*</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für AUTOSAR-Methodik- und Prozessbeschreibungen. Für Prozessmodellierer und Tool-Entwickler verbindlich:</p>\n<ul class=\"fig-list\"><li>Aufgaben (<code>Task Definition</code>) sind deklarativ und prozessunabhängig wiederverwendbar.\n</li><li>Kardinalitäten von <code>0..*</code> für Ein- und Ausgänge kennzeichnen optionale bzw. mehrfache Artefakte.\n</li><li>Rollen und Werkzeuge sind als wiederverwendbare Definitionsbausteine von konkreten Instanziierungen (Use Cases) entkoppelt.\n</li></ul>"}], "trans": [{"from": "FIG-76e4a5f8f063993d", "to": "FIG-08eb36f0a7c274bc", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-08eb36f0a7c274bc", "to": "FIG-e26d09c9bb86b012", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
